import { VerifiedMark, Card } from "march/ui"

// profil adı: koyu kartta büyük ad ve altın rozet
export function ProfileName() {
  return <Card m:theme="night">
    <span sx={{ text: ["xl", "bold"] }}>HADİ Koşu Kulübü <VerifiedMark size="lg" m:color="brand-gold" label="Onaylı kulüp" /></span>
  </Card>
}

import { VerifiedMark, Avatar } from "march/ui"

// yorumlar: onaylı hesapların adının yanında rozet
const comments = [{ name: "Fotoğraf Atölyesi", ok: true, text: "Işık harika" }, { name: "Can", ok: false, text: "Katılıyorum" }]

export function CommentList() {
  return <div sx={{ flex: "col", gap: 2 }}>
    {comments.map((c) => <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <Avatar name={c.name} size="sm" />
      <span><strong>{c.name}</strong> {c.ok ? <VerifiedMark size="sm" /> : null}: {c.text}</span>
    </div>)}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { VerifiedMarkLab } from "./VerifiedMarkLab.tsx"

// VerifiedMarkLab'in testleri: kaydedince Testler sekmesinde çalışır
test("rozet bir resim, adı label", () => {
  const s = renderTest(() => <VerifiedMarkLab />)
  expect(s.get(".lab-own")?.getAttribute("role")).toBe("img")
  expect(s.get(".lab-own")?.getAttribute("aria-label")).toBe("Onaylı işletme")
})

test("label={false} süs: ekran okuyucudan gizli", () => {
  const s = renderTest(() => <VerifiedMarkLab />)
  expect(s.get(".lab-deco")?.getAttribute("aria-hidden")).toBe("true")
})

test("metin ikon yazılır", () => {
  const s = renderTest(() => <VerifiedMarkLab />)
  expect(s.get(".lab-text")?.textContent).toContain("✔")
})
